import logging
import time
from taf.internal.rpc.pyro.exception import TryServeralTimesFailure


def upload_file(local_path, remote_path, connection):

    fp = connection.files
    log_msg = "Uploading file to {}:\n"
    log_msg += "Remote path: {}"
    log_msg = log_msg.format(connection, remote_path)
    logging.info(log_msg)

    logging.info("Uploading file: {}".format(local_path))
    fp.put(local_path, remote_path)


def download_file(remote_path, connection, local_path):
    fp = connection.files
    log_msg = "Downloading file to {}:\n"
    log_msg += "Remote path: {}"
    log_msg = log_msg.format(connection, remote_path)
    logging.info(log_msg)

    logging.info("Downloading file: {}".format(local_path))
    fp.get(remote_path, local_path)


def download_files(remote_paths, connection, local_dir):
    local_dir = local_dir.replace("\\", "/")
    local_dir = local_dir + '/' if not local_dir.endswith('/') else local_dir
    for remote_file_path in remote_paths:
        remote_file_name = remote_file_path.replace("\\", "/").split('/')[-1]
        download_file(remote_file_path, connection, local_dir + remote_file_name)


def try_several_times(func, tries, interval, *args, **kwargs):

    tries_left = tries
    while True:
        result = func(*args, **kwargs)
        tries_left = tries_left - 1
        if not result:
            if tries_left > 0:
                time.sleep(interval)
                continue
            raise TryServeralTimesFailure("tried {} {} times with interval {}".
                                          format(func.__name__, tries, interval))
        else:
            return result


def try_several_times_with_timeout_increment(func, tries, interval, start_timeout, timeout_increment, *args, **kwargs):

    tries_left = tries
    timeout = start_timeout
    while True:
        result = func(timeout, *args, **kwargs)
        tries_left = tries_left - 1
        if not result:
            if tries_left > 0:
                time.sleep(interval)
                timeout = timeout + timeout_increment
                continue
            raise TryServeralTimesFailure("tried {} {} times with interval {}, start timeout is {}, last timeout is {}".
                                          format(func.__name__, tries, interval, start_timeout, timeout))
        else:
            return result
